import{_ as t,o as n,c as e,am as p}from"./chunks/framework._FJXuPhs.js";const d=JSON.parse('{"title":"SpringCloud_组件基本使用_Zipkin","description":"","frontmatter":{"title":"SpringCloud_组件基本使用_Zipkin","excerpt":"SpringCloud_组件基本使用_Zipkin","date":"2023-12-01 13:56:45","updated":"2023-12-01 13:56:45"},"headers":[],"relativePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_Zipkin.md","filePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_Zipkin.md","lastUpdated":null}'),i={name:"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_Zipkin.md"};function s(l,a,r,o,c,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h3 id="_1、什么是-sleuth" tabindex="-1">1、什么是 Sleuth <a class="header-anchor" href="#_1、什么是-sleuth" aria-label="Permalink to &quot;1、什么是 Sleuth&quot;">​</a></h3><p>Sleuth是Spring Cloud的组件之一，它为Spring Cloud实现了一种分布式追踪解决方案。</p><p>一般是和 zipkin 或者其他基于日志的追踪系统一起使用的。</p><p>简单理解：sleuth 是链路追踪器，将链路信息放到日志中，zipkin 是链路分析器，将链路日志进行可视化分析和聚合检索。</p><h3 id="_2、zipkin是什么" tabindex="-1">2、Zipkin是什么 <a class="header-anchor" href="#_2、zipkin是什么" aria-label="Permalink to &quot;2、Zipkin是什么&quot;">​</a></h3><p>Zipkin是一个分布式追踪系统。它有助于收集对服务架构中的延迟问题进行故障排除所需的计时数据。功能包括收集和查找这些数据。</p><p>Zipkin is a distributed tracing system. It helps gather timing data needed to troubleshoot latency problems in service architectures. Features include both the collection and lookup of this data.</p><p>在微服务架构中，随着业务的不断扩张，服务之间互相调用会越来越复杂。而Zipkin能收集服务中的一些数据，我们能够通过明显的可视化效果去查看链路中的情况（支持日志聚合，进行可视化展示和全文检索）。</p><p><strong>分布式链路追踪（Distributed Tracing）</strong>： 将一次分布式请求还原成调用链路，进行日志记录，性能监控并将一次分布式请求的调用情况集中展示。比如各个服务节点上的耗时、请求具体到达哪台机器上、每个服务节点的请求状态等等。</p><p>常用的链路追踪技术还有好几种，有兴趣可以去了解一下。</p><ul><li><a href="https://skywalking.apache.org/zh/2020-04-19-skywalking-quick-start/" target="_blank" rel="noreferrer">https://skywalking.apache.org/zh/2020-04-19-skywalking-quick-start/</a></li><li><a href="https://logging.apache.org/log4j/2.x/" target="_blank" rel="noreferrer">https://logging.apache.org/log4j/2.x/</a></li><li><a href="https://github.com/pinpoint-apm/pinpoint" target="_blank" rel="noreferrer">https://github.com/pinpoint-apm/pinpoint</a></li></ul><hr><h3 id="_3、sleuth入门" tabindex="-1">3、Sleuth入门 <a class="header-anchor" href="#_3、sleuth入门" aria-label="Permalink to &quot;3、Sleuth入门&quot;">​</a></h3><blockquote><p>Sleuth 术语</p></blockquote><ul><li>Trace (一条完整链路–包含很多span(微服务接口)) <ul><li>由一组Trace Id（贯穿整个链路）相同的Span串联形成一个树状结构。为了实现请求跟踪，当请求到达分布式系统的入口端点时，只需要服务跟踪框架为该请求创建一个唯一的标识（即TraceId），同时在分布式系统内部流转的时候，框架始终保持传递该唯一值，直到整个请求的返回。那么我们就可以使用该唯一标识将所有的请求串联起来，形成一条完整的请求链路。</li></ul></li><li>Span <ul><li>代表了一组基本的工作单元。为了统计各处理单元的延迟，当请求到达各个服务组件的时候，也通过一个唯一标识（SpanId）来标记它的开始、具体过程和结束。通过SpanId的开始和结束时间戳，就能统计该span的调用时间，除此之外，我们还可以获取如事件的名称。请求信息等元数据。</li></ul></li><li>Annotation <ul><li>用它记录一段时间内的事件，内部使用的重要注释： <ul><li>cs（Client Send）客户端发出请求，开始一个请求的生命</li><li>sr（Server Received）服务端接受到请求开始进行处理， sr－cs = 网络延迟（服务调用的时间）</li><li>ss（Server Send）服务端处理完毕准备发送到客户端，ss - sr = 服务器上的请求处理时间</li><li>cr（Client Reveived）客户端接受到服务端的响应，请求结束。 cr - sr = 请求的总时间</li></ul></li></ul></li></ul><blockquote><p>Sleuth 使用</p></blockquote><p>在pom.xml文件添加Sleuth依赖</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> &lt;!--sleuth依赖--&gt;</span></span>
<span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>	&lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt;</span></span>
<span class="line"><span>	&lt;artifactId&gt;spring-cloud-starter-sleuth&lt;/artifactId&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><p>项目整合 sleuth 后，在日志输出会多一些链路信息。</p><p>我们在启动这个微服务后，调用其中某个请求，可以在控制台观察到sleuth的日志输出</p><h3 id="_4、链路解决方案-sleuth-zipkin" tabindex="-1">4、链路解决方案 <strong>Sleuth</strong> + <strong>Zipkin</strong> <a class="header-anchor" href="#_4、链路解决方案-sleuth-zipkin" aria-label="Permalink to &quot;4、链路解决方案 **Sleuth** + **Zipkin**&quot;">​</a></h3><p>使用 Zipkin 需要下载一下他的服务端： <a href="https://zipkin.io/pages/quickstart.html" target="_blank" rel="noreferrer">https://zipkin.io/pages/quickstart.html</a></p><p>官方文档里面有介绍他对应的下载和启动方式。</p><p>通过浏览器访问 <a href="http://localhost:9411/" target="_blank" rel="noreferrer">http://localhost:9411</a>访问</p><p>Zipkin 跟 Nacos 类似，需要启动他的服务端程序，并在微服务模块中添加客户端相关的配置。</p><blockquote><p><strong>Sleuth</strong> + <strong>Zipkin</strong> 集成</p></blockquote><p>这里是选用 ZipKin客户端和Sleuth 进行集成。</p><p>依赖</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>    &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt;</span></span>
<span class="line"><span>    &lt;artifactId&gt;spring-cloud-starter-zipkin&lt;/artifactId&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><p>配置文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#配置zipkin</span></span>
<span class="line"><span>  zipkin:</span></span>
<span class="line"><span>    base-url: http://192.168.31.60:9411</span></span>
<span class="line"><span>    discovery-client-enabled: false  # 不要让nacos把zipkin注册进去（可以不写）</span></span>
<span class="line"><span>  sleuth:</span></span>
<span class="line"><span>    sampler:</span></span>
<span class="line"><span>      probability: 1.0</span></span></code></pre></div><p>启动后，便可以在 Zipkin 观察该服务下的请求链路。</p><blockquote><p>持久化操作</p></blockquote><p>Zipkin 默认是将数据保存到内存，生产环境一般是选择持久化到本地。</p><p><strong>Zipkin</strong> 提供可插拔数据存储方式，下面这些都支持：In-Memory、MySql、Cassandra 以及 Elasticsearch。</p><blockquote><p>使用mysql实现数据持久化操作</p></blockquote><p>略，待更新</p><p>to be contined....</p><hr><p>参考：</p><ul><li><a href="https://zipkin.io/pages/quickstart" target="_blank" rel="noreferrer">https://zipkin.io/pages/quickstart</a></li><li><a href="https://blog.csdn.net/qq_40587263/article/details/117338097" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_40587263/article/details/117338097</a></li><li><a href="https://zhuanlan.zhihu.com/p/71024024" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/71024024</a></li></ul>`,41)])])}const g=t(i,[["render",s]]);export{d as __pageData,g as default};
